  on public.posts for update
  using (author_id = auth.uid())
  with check (author_id = auth.uid());

create policy "Users can delete own posts"
  on public.posts for delete
  using (author_id = auth.uid());

-- R4: A comment is visible to exactly the people who can read the post it belongs to
create policy "Comments visible per post visibility"
  on public.comments for select
  using (
    exists (
      select 1 from public.posts
      where public.posts.id = comments.post_id
      and (public.posts.published_at is not null and public.posts.published_at < now())
      and (public.posts.unpublish_at is null or public.posts.unpublish_at > now())
    )
  );

-- R5: Signed-in users can comment as themselves on readable posts
create policy "Signed-in users can comment on readable posts"
  on public.comments for insert
  with check (
    auth.role() = 'authenticated'
    and author_id = auth.uid()
    and exists (
      select 1 from public.posts
      where public.posts.id = comments.post_id
      and (public.posts.published_at is not null and public.posts.published_at < now())
      and (public.posts.unpublish_at is null or public.posts.unpublish_at > now())
    )
  );

