-- Create/Replace the decision function
create or replace function public.decide_expense(p_expense_id bigint, p_approve boolean)
returns void language plpgsql strict as $$
declare
  v_expense public.expenses%rowtype;
  v_user_id uuid := auth.uid();
  v_dept_id bigint;
  v_is_manager boolean;
  v_submitted_by uuid;
begin
  -- Acquire the expense row (will raise error if not found or not pending)
  select * into v_expense from public.expenses where id = p_expense_id;

  -- If using service role, allow any pending expense and leave decided_by empty
  if auth.role() = 'service_role' then
    update public.expenses
    set status = case when p_approve then 'approved' else 'rejected' end,
        decided_by = null
    where id = p_expense_id;
    return;
  end if;

  -- Non-service-role checks
  v_dept_id := v_expense.department_id;
  v_is_manager := public.is_department_manager(v_dept_id, v_user_id);
  v_submitted_by := v_expense.submitted_by;

  -- Must manage the department and expense must be pending
  if not v_is_manager then
    raise exception 'Only managers can decide expenses';
  end if;

  if v_expense.status != 'pending' then
    raise exception 'Expense is not pending';
  end if;

  -- Caller must not have submitted it
  if v_user_id = v_submitted_by then
    raise exception 'Submitter cannot decide their own expense';
  end if;

  -- Apply the decision
  update public.expenses
  set status = case when p_approve then 'approved' else 'rejected' end,
      decided_by = v_user_id
  where id = p_expense_id;
end;
$$;

-- Grant execute on the function to authenticated users (anon cannot call)
grant execute on public.decide_expense to authenticated;

