  -- Caller must not be the submitter
  if v_expense.submitted_by = v_user_id then
    raise exception 'Caller cannot decide on an expense they submitted', using errcontext;
  end if;

  -- Apply the decision
  update public.expenses set status = case when p_approve then 'approved' else 'rejected' end, decided_by = v_user_id where id = p_expense_id;
end;
$$;

