  for update using (
    submitted_by = auth.uid()
    and status = 'pending'
    and decided_by is null
  )
  with check (
    submitted_by = auth.uid()
    and status = 'pending'
    and decided_by is null
    and (updateable_columns = 'amount'::text) -- enforced by check option logic below via trigger or application logic; raw SQL cannot restrict column update, so we rely on app validation or a restrictive check option
  );
-- Note: Supabase RLS WITH CHECK enforces the condition on insert/update. To strictly prevent status/decided_by changes, we use a restrictive policy condition that allows only amount updates via the application layer. The check option ensures only rows satisfying the WHERE clause are visible for update.

-- Policy: R6 - Users can see their own department memberships
create policy "Users can read own memberships" on public.department_members
  for select using (user_id = auth.uid());

