-- Create the decision function (R4, R5)
create or replace function public.decide_expense(p_expense_id bigint, p_approve boolean) returns void language plpgsql strict as $$
declare
  v_expense public.expenses%rowtype;
  v_dept_id bigint;
  v_manager boolean;
begin
  -- Acquire lock and read current state
  select * into v_expense from public.expenses where id = p_expense_id for update;

  -- R5: Service role bypasses RLS; if called via service_role, auth.uid() is null or we check context.
  -- We check caller authorization using auth.uid(). If service_role is used, the trigger/context
  -- should set search_path or we rely on the fact that service_role bypasses RLS entirely.
  -- However, to enforce R4 logic when called from auth, we check:
  if not current_setting('role') = 'service_role' then
    -- R4: Caller must manage the expense's department and expense must be pending
    -- and caller did not submit it.
    v_dept_id := v_expense.department_id;
    v_manager := public.is_manager_of_department(v_dept_id);

    if not v_manager then
      raise exception 'Caller is not a manager of department %', v_dept_id using errcontext;
    end if;

    if v_expense.status != 'pending' then
      raise exception 'Expense is not pending';
    end if;

    if v_expense.submitted_by = auth.uid() then
      raise exception 'Caller cannot decide on an expense they submitted';
    end if;
  end if;

  -- Apply the decision
  if p_approve then
    update public.expenses set status = 'approved', decided_by = auth.uid() where id = p_expense_id;
  else
    update public.expenses set status = 'rejected', decided_by = auth.uid() where id = p_expense_id;
  end if;

  -- R5 exception: If called via service_role, leave decided_by empty
  if current_setting('role') = 'service_role' then
    update public.expenses set decided_by = null where id = p_expense_id;
  end if;

end;
$$;

