returns void
language plpgsql
security invoker
as $$
declare
    v_expense public.expenses%rowtype;
    v_dept_id bigint;
    v_manager_count integer;
    v_is_manager boolean;
    v_submitter_id uuid;
begin
    -- Fetch the expense; if not found, raise error
    select * into v_expense from public.expenses where id = p_expense_id;
    if not found then
        raise exception 'Expense with ID % not found', p_expense_id using errcontext;
    end if;

