    select department_id, is_manager into v_dept_id, v_is_manager
    from public.department_members
    where user_id = auth.uid() and department_id = v_expense.department_id;

    if not found or not v_is_manager then
        raise exception 'Caller is not a manager of the expense department';
    end if;

    -- Rule R4: Caller must not be the submitter
    if v_expense.submitted_by = auth.uid() then
        raise exception 'Caller cannot decide on an expense they submitted';
    end if;

    -- Additional check: ensure the caller manages the department (already done above)
    -- Update the expense status and decided_by
    if p_approve then
        update public.expenses
        set status = 'approved', decided_by = auth.uid()
        where id = p_expense_id;
    else
