-- Policy: R1 - Any signed-in user can create an organization
-- The creator is set to the signing-in user via auth.uid() default
create policy "orgs_insert_policy" on public.orgs
  for insert with check (auth.role() = 'authenticated');

-- Policy: R2 - Creator can add themselves as owner when no members exist
-- Also allows creator to insert membership when org has no members yet
create policy "org_members_insert_policy" on public.org_members
  for insert with check (
    -- Creator adding themselves as owner when org has no members
    (role = 'owner' and 
     auth.uid() = (select created_by from public.orgs where id = org_id) and
     not exists (select 1 from public.org_members where org_id = org_id)) or
    -- Authenticated user adding another user as member (handled by R4 logic below, 
    -- but this allows the initial insert pattern)
    (role = 'member' and auth.role() = 'authenticated')
  );

-- Policy: R3 - Members can see orgs they belong to and their membership rows
-- Creator can see org before joining
create policy "orgs_select_policy" on public.orgs
  for select using (
    -- Creator can see their own org
    auth.role() = 'authenticated' and created_by = auth.uid() or
    -- Member can see orgs they belong to exists
    exists (
      select 1 from public.org_members
      where org_id = id and user_id = auth.uid()
    )
  );

create policy "org_members_select_policy" on public.org_members
  for select using (
    -- Creator can see membership before joining
    auth.role() = 'authenticated' and auth.uid() = (select created_by from public.orgs where id = org_id) or
    -- Member can see memberships of orgs they belong to
    exists (
      select 1 from public.org_members m2
      where m2.org_id = org_id and m2.user_id = auth.uid()
    )
  );

-- Policy: R4 - Owners and admins can add/remove member role memberships
-- Owners can give admin/owner roles and change roles
create policy "org_members_update_policy" on public.org_members
  for update using (
    -- Check if user has permission to modify this membership
    -- Owners and admins can modify member roles
    exists (
      select 1 from public.org_members m2
      where m2.org_id = org_id 
        and m2.user_id != auth.uid()  -- modifying someone else's membership
        and m2.role in ('owner', 'admin')
        and auth.uid() in (
          -- Check if current user is owner or admin of this org
          select user_id from public.org_members m3
          where m3.org_id = org_id and m3.role = 'owner'
        )
    ) or
    -- Users can update their own role if they are the creator and org has no members (R2)
    (user_id = auth.uid() and 
     not exists (select 1 from public.org_members where org_id = org_id and user_id != auth.uid()))
  )
  with check (true); -- Allow the update to proceed if passing RLS check

-- Policy: R5 - Any member can leave except if they are the only owner
create policy "org_members_delete_policy" on public.org_members
  for delete using (
    -- User can delete their own membership
    user_id = auth.uid() and
    -- Except if they are the only owner of the organization
    not (
      -- Check if user is the only owner
      exists (
        select 1 from public.org_members m2
        where m2.org_id = org_id and m2.role = 'owner'
      ) and 
      not exists (
        select 1 from public.org_members m3
        where m3.org_id = org_id and m3.role != 'owner'
      )
    )
  );

-- Policy: R6 - Nobody can change their own role (enforced via update policy above)
-- No specific policy needed as R6 is handled by the update check in R4

-- Policy: R7 - Only owners can rename organization
create policy "orgs_update_policy" on public.orgs
  for update using (
    auth.role() = 'authenticated' and
    auth.uid() = (select created_by from public.orgs where id = id)
  )
  with check (
    auth.role() = 'authenticated' and
    auth.uid() = (select created_by from public.orgs where id = id)
  );

-- Policy: R8 - Anonymous visitors cannot see or change anything
-- Handled by the auth.role() = 'authenticated' checks above

-- Policy: R9 - Server-side code using service role keeps full access
-- service_role bypasses RLS by default, no additional policy needed

-- Grant necessary permissions
grant all on public.orgs to service_role;
grant all on public.org_members to service_role;

-- Revoke public access (ensure anon cannot bypass)
revoke all on public.orgs from public;
revoke all on public.org_members from public;
