-- Enable RLS on tables
alter table public.events enable row level security;
alter table public.delegations enable row level security;

-- Events: owners full control; delegates see non-private only, editing if granted
create policy "Owners full control on events"
  on public events
  using (auth.uid() = owner_id)
  with check (auth.uid() = owner_id);

create policy "Delegates read non-private events"
  on public events
  for select
  using (
    exists (
      select 1 from public.delegations
      where (grantor_id = owner_id or grantor_id = auth.uid())
        and delegate_id = auth.uid()
        and (can_edit or not is_private)
        and (expires_at is null or expires_at > now())
    )
    and not is_private
  );

create policy "Delegates edit non-private events if granted"
  on public events
  for update, delete
  using (
    exists (
      select 1 from public.delegations
      where grantor_id = owner_id
        and delegate_id = auth.uid()
        and can_edit
        and (expires_at is null or expires_at > now())
    )
    and not is_private
  )
  with check (
    exists (
      select 1 from public.delegations
      where grantor_id = owner_id
        and delegate_id = auth.uid()
        and can_edit
        and (expires_at is null or expires_at > now())
    )
    and not is_private
  );

-- Delegations: owners manage their own; delegates see given delegations
create policy "Owners manage own delegations"
  on public delegations
  for all
  using (grantor_id = auth.uid())
  with check (grantor_id = auth.uid());

create policy "Delegates see own delegations"
  on public delegations
  for select
  using (delegate_id = auth.uid());

-- Busy slots view: owner's events + delegated non-private events
create view public.busy_slots as
select owner_id, starts_at, ends_at
from public.events
where owner_id = auth.uid()
   or exists (
     select 1 from public.delegations
     where grantor_id = events.owner_id
       and delegate_id = auth.uid()
       and (expires_at is null or expires_at > now())
       and not is_private
   );

-- Grant service_role full access
grant all on public.events to service_role;
grant all on public.delegations to service_role;
grant all on public.busy_slots to service_role;
