```sql
-- Enable RLS on events and delegations
alter table public.events enable row level security;
alter table public.delegations enable row level security;

-- Helper function: check if a delegation is valid (unexpired and grantor matches)
create or replace function public.is_valid_delegation(grantor_id uuid, delegate_id uuid)
returns boolean language sql strict as $$
  select exists (
    select 1 from public.delegations
    where grantor_id = $1
      and delegate_id = $2
      and (expires_at is null or expires_at > now())
  );
$$;

-- Policy: Owners full control over their events
create policy "Owners manage own events" on public.events
  using ( owner_id = auth.uid() )
  with check ( owner_id = auth.uid() );

-- Policy: Delegates can read non-private events of grantor
create policy "Delegates read non-private events" on public.events
  using (
    is_private = false
    and owner_id != auth.uid()
    and exists (
      select 1 from public.delegations
      where grantor_id = owner_id
        and delegate_id = auth.uid()
        and (expires_at is null or expires_at > now())
    )
  );

-- Policy: Delegates with edit permission can edit/delete non-private events
create policy "Delegates edit non-private events" on public.events
  using (
    is_private = false
    and can_edit = true
    and owner_id != auth.uid()
    and exists (
      select 1 from public.delegations
      where grantor_id = owner_id
        and delegate_id = auth.uid()
        and (expires_at is null or expires_at > now())
    )
  )
  with check (
    is_private = false
    and can_edit = true
    and owner_id != auth.uid()
    and exists (
      select 1 from public.delegations
      where grantor_id = owner_id
        and delegate_id = auth.uid()
        and (expires_at is null or expires_at > now())
    )
  );

-- Policy: Owners can manage their own delegations
create policy "Owners manage own delegations" on public.delegations
  using ( grantor_id = auth.uid() )
  with check ( grantor_id = auth.uid() );

-- Policy: Delegates can see delegations given to them
create policy "Delegates see own delegations" on public.delegations
  using ( delegate_id = auth.uid() );

-- Create the busy_slots view
create view public.busy_slots as
select owner_id, starts_at, ends_at
from public.events
where owner_id = auth.uid()
   or exists (
     select 1 from public.delegations
     where grantor_id = events.owner_id
       and delegate_id = auth.uid()
       and (expires_at is null or expires_at > now())
   )
grant select to anon, authenticated, service_role;

-- Grants for service_role (full access)
grant all on public.events to service_role;
grant all on public.delegations to service_role;
grant usage on schema public to service_role;
